package io.github.kubanik21crypto.benger;
import org.junit.Test;import static org.junit.Assert.*;import java.security.*;import java.security.spec.*;import java.nio.charset.StandardCharsets;import javax.crypto.*;import javax.crypto.spec.*;import org.json.JSONObject;
public class PickerHandoffCryptoTest {
 static KeyPair pair()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));return g.generateKeyPair();}
 static String open(String response,KeyPair client,String nonce,String origin)throws Exception{JSONObject value=new JSONObject(response);KeyAgreement k=KeyAgreement.getInstance("ECDH");k.init(client.getPrivate());k.doPhase(KeyFactory.getInstance("EC").generatePublic(new X509EncodedKeySpec(PickerHandoffCrypto.unhex(value.getString("serverKey")))),true);MessageDigest hash=MessageDigest.getInstance("SHA-256");hash.update(k.generateSecret());hash.update(nonce.getBytes(StandardCharsets.UTF_8));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(hash.digest(origin.getBytes(StandardCharsets.UTF_8)),"AES"),new GCMParameterSpec(128,PickerHandoffCrypto.unhex(value.getString("iv"))));cipher.updateAAD((nonce+"\n"+origin).getBytes(StandardCharsets.UTF_8));return new String(cipher.doFinal(PickerHandoffCrypto.unhex(value.getString("ciphertext"))),StandardCharsets.UTF_8);}
 @Test public void handoffIsEncryptedAndBoundToBrowserKeyOriginAndNonce()throws Exception{KeyPair client=pair();String nonce="a".repeat(64),origin="http://benger-example.localhost:48765",plain="SYNTHETIC_NOT_REAL_TOKEN",response=PickerHandoffCrypto.seal(plain,PickerHandoffCrypto.hex(client.getPublic().getEncoded()),nonce,origin);assertFalse(response.contains(plain));assertEquals(plain,open(response,client,nonce,origin));try{open(response,client,nonce,origin+"wrong");fail();}catch(GeneralSecurityException expected){}try{open(response,pair(),nonce,origin);fail();}catch(GeneralSecurityException expected){}try{open(response,client,"b".repeat(64),origin);fail();}catch(GeneralSecurityException expected){}}
 @Test public void malformedKeysAndCiphertextTamperingFailClosed()throws Exception{try{PickerHandoffCrypto.seal("synthetic","bad-key","nonce","origin");fail();}catch(Exception expected){}KeyPair client=pair();String nonce="a".repeat(64),origin="http://benger-example.localhost:48765";JSONObject value=new JSONObject(PickerHandoffCrypto.seal("synthetic",PickerHandoffCrypto.hex(client.getPublic().getEncoded()),nonce,origin));byte[] bytes=PickerHandoffCrypto.unhex(value.getString("ciphertext"));bytes[0]^=1;value.put("ciphertext",PickerHandoffCrypto.hex(bytes));try{open(value.toString(),client,nonce,origin);fail();}catch(GeneralSecurityException expected){}}
}
